using System.Collections.Generic;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "DiceActionLogic_RandomTarget_RandomPurifyCorruptAction", menuName = "Data/Battle/Logics/Dice Action/Random Target Dice - Random Purify Corrupt Action")]
public class DiceActionLogic_RandomTarget_RandomPurifyCorruptAction : DiceActionLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	public override void ActionGrabbed()
	{
		base.ActionGrabbed();
		List<GameObject> list = new List<GameObject>();
		BattleAction battleAction = ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance.ActionFace.BattleAction;
		GameObject gameObject = currentActiveUnits.IsUnitWithElectrostaticField();
		List<GameObject> list2 = currentActiveUnits.GetCurrentActiveUnits();
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayerOrCompanionsCurrentActionInstance())
		{
			if ((bool)gameObject)
			{
				if (battleAction is PurifyAction || battleAction is ConfuseAction)
				{
					ReferenceSingleton<BattleHandler>.Instance.RandomPurifySecondTarget = gameObject;
				}
				list.Add(gameObject);
			}
			else
			{
				if (battleAction is PurifyAction || battleAction is ConfuseAction)
				{
					ReferenceSingleton<BattleHandler>.Instance.RandomPurifySecondTarget = list2.PickRandom();
				}
				GameObject item = list2.PickRandom();
				list.Add(item);
			}
		}
		else
		{
			if (battleAction is PurifyAction || battleAction is ConfuseAction)
			{
				ReferenceSingleton<BattleHandler>.Instance.RandomPurifySecondTarget = list2.PickRandom();
			}
			GameObject item2 = list2.PickRandom();
			list.Add(item2);
		}
		actionGameState.SetTargetOnActions(list);
		if ((bool)gameObject)
		{
			actionGameState.SetHighlightTargetOnActions(list);
		}
		else
		{
			actionGameState.SetHighlightTargetOnActions(list2);
		}
	}
}
